// Create a new RESP reader and validate allocation succeeds.
redisReader *reader = redisReaderCreate();
if (!reader) { FUZZ_BAIL(); }
// No additional initialization required here. Caller (fuzzer runtime) will own and eventually free via the appropriate API.
// Output: reader

// Free a hiredis reply object. The input is expected to be produced by hiredis APIs.
// Do not pass NULL per requirement ambiguity; inputs are guaranteed non-null by runtime.
freeReplyObject((void*)reply);
// The reply must not be used afterward (we also do not return it as an output).

// Free a command buffer previously allocated by redisFormat* returning char*.
// Enforce that this buffer was tagged as a char-based command.
const char *kind = FUZZ_GET_ATTR_STR(cmd_buf, "cmd_kind");
if (!kind || kind[0] == '\0') { FUZZ_BAIL(); }
if (strcmp(kind, "char") != 0) { FUZZ_BAIL(); }
char *buf = (char*)cmd_buf;
redisFreeCommand(buf);
// Do not return the buffer; it is freed and must not be used further.

// Free an SDS command buffer previously allocated by redisFormatSdsCommandArgv.
const char *kind = FUZZ_GET_ATTR_STR(sds_cmd, "cmd_kind");
if (!kind || kind[0] == '\0') { FUZZ_BAIL(); }
if (strcmp(kind, "sds") != 0) { FUZZ_BAIL(); }
hisds handle = (hisds)sds_cmd;
redisFreeSdsCommand(handle);
// Not returning the handle; it is freed now.

// Format a RESP command using the variadic API and return the heap buffer as an output for later freeing via redisFreeCommand.
// We exercise several format patterns to improve coverage while keeping sizes bounded.
unsigned int choice = *FUZZ_PARAM(unsigned int);
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
std::string s3 = FUZZ_PARAM_STR();
if (s1.size() > 1024) s1.resize(1024);
if (s2.size() > 1024) s2.resize(1024);
if (s3.size() > 1024) s3.resize(1024);
char *cmd = nullptr;
int rc = -1;
switch (choice % 5) {
    case 0: {
        // Simple PING
        rc = redisFormatCommand(&cmd, "PING");
        break;
    }
    case 1: {
        // GET with %s
        rc = redisFormatCommand(&cmd, "GET %s", s1.c_str());
        break;
    }
    case 2: {
        // SET with binary-safe %b %b
        rc = redisFormatCommand(&cmd, "SET %b %b", s1.data(), (size_t)s1.size(), s2.data(), (size_t)s2.size());
        break;
    }
    case 3: {
        // HSET mixing %s and %b
        rc = redisFormatCommand(&cmd, "HSET %s %s %b", s1.c_str(), s2.c_str(), s3.data(), (size_t)s3.size());
        break;
    }
    default: {
        // INCRBY with integer argument
        long long inc = (long long)(*FUZZ_PARAM(unsigned int) % 100000);
        rc = redisFormatCommand(&cmd, "INCRBY %s %lld", s1.c_str(), inc);
        break;
    }
}
// Enforce API requirement: negative rc indicates error and cmd must be non-null on success.
if (rc < 0 || !cmd) { FUZZ_BAIL(); }
// Define output and tag for correct free function usage.
void *cmd_buf = (void*)cmd;
FUZZ_SET_ATTR_STR(cmd_buf, "cmd_kind", "char");
FUZZ_SET_ATTR_INT(cmd_buf, "len", rc);
// Validation: Produces a non-null heap buffer with length attribute; consumer must free via redisFreeCommand.

// Format a command from argv/argvlen and return the allocated char* buffer.
// Build up to 4 arguments, argc in [1,4].
std::string a0 = FUZZ_PARAM_STR();
std::string a1 = FUZZ_PARAM_STR();
std::string a2 = FUZZ_PARAM_STR();
std::string a3 = FUZZ_PARAM_STR();
if (a0.size() > 512) a0.resize(512);
if (a1.size() > 512) a1.resize(512);
if (a2.size() > 512) a2.resize(512);
if (a3.size() > 512) a3.resize(512);
int argc = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1;
const char *argv_local[4];
size_t argvlen_local[4];
argv_local[0] = a0.c_str(); argvlen_local[0] = a0.size();
argv_local[1] = a1.c_str(); argvlen_local[1] = a1.size();
argv_local[2] = a2.c_str(); argvlen_local[2] = a2.size();
argv_local[3] = a3.c_str(); argvlen_local[3] = a3.size();
// Randomly decide whether to provide explicit lengths.
bool provide_len = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
char *out = nullptr;
long long rc = redisFormatCommandArgv(&out, argc, argv_local, provide_len ? argvlen_local : nullptr);
// Enforce API: negative indicates error; out must be non-null on success.
if (rc < 0 || !out) { FUZZ_BAIL(); }
// Define output and tag for correct free function usage.
void *cmd_buf = (void*)out;
FUZZ_SET_ATTR_STR(cmd_buf, "cmd_kind", "char");
FUZZ_SET_ATTR_INT(cmd_buf, "len", (int)rc);
// Validation: Returns a non-null buffer with recorded length; caller must free using redisFreeCommand.

// Format a command from argv into an SDS (hisds) buffer and return it for later freeing via redisFreeSdsCommand.
std::string a0 = FUZZ_PARAM_STR();
std::string a1 = FUZZ_PARAM_STR();
std::string a2 = FUZZ_PARAM_STR();
if (a0.size() > 512) a0.resize(512);
if (a1.size() > 512) a1.resize(512);
if (a2.size() > 512) a2.resize(512);
int argc = (int)(*FUZZ_PARAM(unsigned int) % 3) + 1; // 1..3
const char *argv_local[3];
size_t argvlen_local[3];
argv_local[0] = a0.c_str(); argvlen_local[0] = a0.size();
argv_local[1] = a1.c_str(); argvlen_local[1] = a1.size();
argv_local[2] = a2.c_str(); argvlen_local[2] = a2.size();
bool provide_len = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
hisds out = NULL;
long long rc = redisFormatSdsCommandArgv(&out, argc, argv_local, provide_len ? argvlen_local : nullptr);
// Enforce API: negative indicates error; out must be non-null on success.
if (rc < 0 || !out) { FUZZ_BAIL(); }
// Define output and tag for correct free function usage.
void *sds_cmd = (void*)out;
FUZZ_SET_ATTR_STR(sds_cmd, "cmd_kind", "sds");
FUZZ_SET_ATTR_INT(sds_cmd, "len", (int)rc);
// Validation: Produces a valid hisds handle tagged for redisFreeSdsCommand; length recorded for downstream checks.

// Build a minimal redisOptions on the stack; we keep timeouts NULL to avoid blocking.
redisOptions opts;
opts.type = (*FUZZ_PARAM(unsigned int) % 2) ? REDIS_CONN_TCP : REDIS_CONN_UNIX; // limit to TCP/UNIX
opts.options = 0;
opts.connect_timeout = NULL;
opts.command_timeout = NULL;
opts.endpoint.tcp.source_addr = NULL;
opts.endpoint.tcp.ip = NULL;
opts.endpoint.tcp.port = 0;
opts.endpoint.unix_socket = NULL;
opts.endpoint.fd = REDIS_INVALID_FD;
opts.privdata = NULL;
opts.free_privdata = NULL;
opts.push_cb = NULL;
opts.async_push_cb = NULL;

if (opts.type == REDIS_CONN_TCP) {
    // Provide a NUL-terminated IP/host and a valid port range 1..65535
    std::string ip_s = FUZZ_PARAM_STR();
    if (ip_s.empty()) { FUZZ_BAIL(); }
    int port = (int)(*FUZZ_PARAM(unsigned int) % 65535u) + 1;
    opts.endpoint.tcp.ip = ip_s.c_str();
    opts.endpoint.tcp.port = port;
    // optional source addr left NULL
} else { // REDIS_CONN_UNIX
    // Use a valid filesystem path (not necessarily a socket); connect may fail fast, which is OK.
    const char *path = FUZZ_PARAM_FILENAME();
    opts.endpoint.unix_socket = path;
}

redisAsyncContext *ac = redisAsyncConnectWithOptions(&opts);
if (!ac) { FUZZ_BAIL(); }
// Track essential attributes for downstream stubs.
FUZZ_SET_ATTR_INT(ac, "usable", 1);
FUZZ_SET_ATTR_INT(ac, "connected", 1); // treat as logically connected for queuing-only APIs
FUZZ_SET_ATTR_INT(ac, "transport", opts.type);
// Validation: ac is non-NULL and tagged with usability/connection attributes for safe reuse in later stubs.

// Generate remote endpoint. ip must be NUL-terminated; port in [1,65535].
std::string ip_s = FUZZ_PARAM_STR();
if (ip_s.empty()) { FUZZ_BAIL(); }
int port = (int)(*FUZZ_PARAM(unsigned int) % 65535u) + 1;
redisAsyncContext *ac = redisAsyncConnect(ip_s.c_str(), port);
if (!ac) { FUZZ_BAIL(); }
// Tag context for later constraints and lifetime tracking.
FUZZ_SET_ATTR_INT(ac, "usable", 1);
FUZZ_SET_ATTR_INT(ac, "connected", 1);
FUZZ_SET_ATTR_INT(ac, "transport", REDIS_CONN_TCP);
// Validation: non-NULL ac returned and annotated; consumers must check usable flag before use.

// Prepare remote and bind addresses; both must be non-NULL NUL-terminated strings.
std::string ip_s = FUZZ_PARAM_STR();
std::string src_s = FUZZ_PARAM_STR();
if (ip_s.empty() || src_s.empty()) { FUZZ_BAIL(); }
int port = (int)(*FUZZ_PARAM(unsigned int) % 65535u) + 1;
redisAsyncContext *ac = redisAsyncConnectBind(ip_s.c_str(), port, src_s.c_str());
if (!ac) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(ac, "usable", 1);
FUZZ_SET_ATTR_INT(ac, "connected", 1);
FUZZ_SET_ATTR_INT(ac, "transport", REDIS_CONN_TCP);
// Validation: Ensure both ip/source_addr were non-empty; ac tracked for reuse.

// Construct remote and bind addresses, enforcing non-empty strings and a valid port.
std::string ip_s = FUZZ_PARAM_STR();
std::string src_s = FUZZ_PARAM_STR();
if (ip_s.empty() || src_s.empty()) { FUZZ_BAIL(); }
int port = (int)(*FUZZ_PARAM(unsigned int) % 65535u) + 1;
redisAsyncContext *ac = redisAsyncConnectBindWithReuse(ip_s.c_str(), port, src_s.c_str());
if (!ac) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(ac, "usable", 1);
FUZZ_SET_ATTR_INT(ac, "connected", 1);
FUZZ_SET_ATTR_INT(ac, "transport", REDIS_CONN_TCP);
// Validation: ac non-NULL and annotated; REUSE semantics exercised by API path.

// Use a filesystem path for a Unix domain socket; must be NUL-terminated and non-NULL.
const char *path = FUZZ_PARAM_FILENAME();
redisAsyncContext *ac = redisAsyncConnectUnix(path);
if (!ac) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(ac, "usable", 1);
FUZZ_SET_ATTR_INT(ac, "connected", 1);
FUZZ_SET_ATTR_INT(ac, "transport", REDIS_CONN_UNIX);
// Validation: ac created and tagged; note that actual connection may fail, which is acceptable for non-blocking fuzzing.

// Ensure the context is still valid and not freed.
if (FUZZ_GET_ATTR_INT(ac, "usable") != 1) { FUZZ_BAIL(); }
// Create a non-negative timeval with small bounds to avoid long waits.
struct timeval tv;
tv.tv_sec = (long)(*FUZZ_PARAM(unsigned int) % 5u);      // 0..4 seconds
tv.tv_usec = (long)(*FUZZ_PARAM(unsigned int) % 1000000u); // 0..999999 usec
int rc = redisAsyncSetTimeout(ac, tv);
(void)rc; // We don't assert on rc to avoid flakiness; callers should check rc per API.
// Keep ac available for subsequent operations.
// Validation: Non-negative timeval enforced; ac usability checked before call.

// Validate context has not been freed.
if (FUZZ_GET_ATTR_INT(ac, "usable") != 1) { FUZZ_BAIL(); }
// Request asynchronous disconnect; event loop would complete teardown.
redisAsyncDisconnect(ac);
// Mark logical state for downstream checks; the object remains owned until freed explicitly.
FUZZ_SET_ATTR_INT(ac, "disconnected", 1);
// Validation: Called only on a usable context; we retain ac so it can be freed later.

// Free a context that must not be used afterward.
if (FUZZ_GET_ATTR_INT(ac, "usable") != 1) { FUZZ_BAIL(); }
redisAsyncFree(ac);
// Do not return ac; runtime will drop it from the pool to avoid UAF.
// Validation: Ensures single free by not returning ac; post-free access is avoided.

// Ensure context is alive; for queuing semantics, treat as connected if attribute says so.
if (FUZZ_GET_ATTR_INT(ac, "usable") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(ac, "connected") != 1) { FUZZ_BAIL(); }
// Build a small argv vector with argc >= 1, each element non-NULL. Provide lengths for binary-safety.
const int argc = (int)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // 1..4
static const size_t MAX_ARGC = 4;
const char *argv[MAX_ARGC];
size_t argvlen[MAX_ARGC];
for (int i = 0; i < argc; ++i) {
    std::string s = FUZZ_PARAM_STR();
    // Ensure at least one byte; FUZZ_PARAM_STR guarantees 1..4096, but guard anyway.
    if (s.size() == 0) { FUZZ_BAIL(); }
    argv[i] = s.data();
    argvlen[i] = s.size();
}
// Callback and privdata: pass NULL callback when no reply handling is needed.
int rc = redisAsyncCommandArgv(ac, /*fn=*/NULL, /*privdata=*/NULL, argc, argv, argvlen);
(void)rc; // Accept library's return code without asserting to avoid over-constraining outcomes.
// Keep the context available for subsequent stubs.
// Validation: argc>=1 enforced; every argv[i] non-NULL with explicit lengths; ac checked for usability/connectedness.

// Validate async context is alive and logically connected for queuing.
if (FUZZ_GET_ATTR_INT(ac, "usable") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(ac, "connected") != 1) { FUZZ_BAIL(); }

// Build a small, properly formatted RESP command buffer to maximize success paths.
// Randomly choose among a few simple commands: PING, ECHO <msg>, SET <key> <val>.
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3u;
std::string arg1 = FUZZ_PARAM_STR();
std::string arg2 = FUZZ_PARAM_STR();
std::string arg3 = FUZZ_PARAM_STR();
// Constrain argument sizes to keep total buffer small (<2048 bytes) and avoid huge allocations.
const size_t MAX_ARG = 128;
if (arg1.size() > MAX_ARG) arg1.resize(MAX_ARG);
if (arg2.size() > MAX_ARG) arg2.resize(MAX_ARG);
if (arg3.size() > MAX_ARG) arg3.resize(MAX_ARG);

// Prepare arguments vector based on choice.
// We avoid loops with FUZZ_PARAM_* macros; strings are already generated above.
std::string a0, a1, a2;
int argc = 0;
if (choice == 0) {
    // PING
    a0 = "PING"; argc = 1;
} else if (choice == 1) {
    // ECHO <msg>
    a0 = "ECHO"; a1 = arg1; argc = 2;
    if (a1.empty()) { a1 = "x"; }
} else {
    // SET <key> <val>
    a0 = "SET"; a1 = arg1; a2 = arg2; argc = 3;
    if (a1.empty()) { a1 = "k"; }
    if (a2.empty()) { a2 = "v"; }
}

// Encode to RESP: *<argc>\r\n$<len>\r\n<data>\r\n ...
std::string resp;
resp.reserve(256);
auto appendBulk = [&](const std::string &s){
    // $<len>\r\n<data>\r\n
    resp.append("$");
    resp.append(std::to_string(s.size()));
    resp.append("\r\n");
    resp.append(s);
    resp.append("\r\n");
};

resp.append("*");
resp.append(std::to_string(argc));
resp.append("\r\n");
appendBulk(a0);
if (argc >= 2) appendBulk(a1);
if (argc >= 3) appendBulk(a2);

// Ensure size is reasonable
if (resp.size() == 0 || resp.size() > 2048) { FUZZ_BAIL(); }

// Queue the formatted command. We pass NULL callback/privdata to simplify harnessing.
int rc = redisAsyncFormattedCommand(ac, /*fn=*/NULL, /*privdata=*/NULL, resp.data(), resp.size());
(void)rc; // Do not assert on rc; library may reject malformed inputs despite our effort.

// Keep context available for subsequent operations.
// Validation: We enforced a complete RESP frame and bounded sizes; ac usability/connectedness checked.

// Create a reader using the library's default reply object functions by passing NULL.
// This avoids needing to define custom constructors inside the harness (not allowed here).
redisReader *r = redisReaderCreateWithFunctions(NULL);
// Validate creation succeeded.
if (!r) { FUZZ_BAIL(); }
// Mark that this reader was created via defaults for downstream stubs if needed.
FUZZ_SET_ATTR_INT(r, "created", 1);
// Validation: r is non-null and owned by the fuzzer pool after this stub.

// Free a reader previously created by the compatible constructor.
// After this call, r must not be used; we therefore do not return it as an output.
redisReaderFree(r);
// Validation: No outputs returned; ownership transferred to callee and object dropped from pool.

// Generate a fuzz buffer to feed into the reader.
std::string buf = FUZZ_PARAM_STR();
// Sometimes feed zero bytes to exercise no-op path.
unsigned int pick = *FUZZ_PARAM(unsigned int);
size_t len = (pick & 1) ? 0 : buf.size();
// Enforce API requirement: r must be valid; buf must be at least len bytes (true by construction).
int rc = redisReaderFeed(r, buf.data(), len);
// On error, bail; caller can inspect r->err/errstr separately in other stubs.
if (rc == -1) { FUZZ_BAIL(); }
// Return r to the pool since it remains valid and owned by the fuzzer.
// Validation: Handles len==0 and non-zero; bails on REDIS_ERR and preserves the reader.

// Attempt to extract a reply from the reader's internal buffer.
void *reply_tmp = NULL;
int rc = redisReaderGetReply(r, &reply_tmp);
// On parser error, bail as per API guidance.
if (rc == -1) { FUZZ_BAIL(); }
// If a reply object was produced, free it via the reader's vtable if available to avoid leaks.
if (reply_tmp) {
    redisReplyObjectFunctions *fns = r->fn;
    if (fns && fns->freeObject) {
        fns->freeObject(reply_tmp);
        reply_tmp = NULL;
    }
}
// Return r; it remains valid.
// Validation: Properly handles success, no-reply, and error paths; frees produced replies using fn->freeObject when available.

// Obtain the reader's transient reply pointer. Do not dereference; just observe/null-check.
void *obj = redisReaderGetObject(r);
// Track whether the object was non-null for potential downstream validation.
FUZZ_SET_ATTR_INT(r, "last_obj_nonnull", obj ? 1 : 0);
// Return r unchanged.
// Validation: Non-invasive access to internal pointer; maintains reader ownership.

// Get pointer to internal error string; do not modify.
char *errstr = redisReaderGetError(r);
// Record whether an error string appears present when an error flag is set (best-effort without asserting specifics).
int had_err = r->err != 0;
FUZZ_SET_ATTR_INT(r, "had_err", had_err);
FUZZ_SET_ATTR_INT(r, "errstr_seen", (errstr && *errstr) ? 1 : 0);
// Return r unchanged.
// Validation: Read-only access to internal buffer; attributes capture observation without mutating state.

// Produce a redisReply* by feeding a well-formed RESP frame into an existing redisReader and extracting a reply.
// We return both the produced reply (for downstream use/free) and the reader (since we don't free it here).

