import random
import struct
from typing import List

ASCII = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-:'

def _rand_choice(r: random.Random, seq):
    return seq[r.randrange(len(seq))]

def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    # Guard against invalid ranges
    if max_len < 0:
        max_len = 0
    if min_len < 0:
        min_len = 0
    if max_len < min_len:
        max_len = min_len
    return ''.join(_rand_choice(r, ASCII) for _ in range(r.randint(min_len, max_len))) if max_len > 0 else ''

def _rand_bytes(r: random.Random, min_len: int, max_len: int) -> bytes:
    # Guard against invalid ranges
    if max_len < 0:
        max_len = 0
    if min_len < 0:
        min_len = 0
    if max_len < min_len:
        max_len = min_len
    n = r.randint(min_len, max_len) if max_len > 0 else 0
    return bytes(r.getrandbits(8) for _ in range(n))

def _int_to_bytes(i: int) -> bytes:
    return str(i).encode('ascii')

def _float_to_bytes(f: float) -> bytes:
    s = ("%.8f" % f).rstrip('0').rstrip('.')
    if s == '':
        s = '0'
    return s.encode('ascii')

def _clip(b: bytes, max_len: int = 512) -> bytes:
    return b[:max_len]

def _make_bulk(r: random.Random, approx: int) -> bytes:
    # Normalize approx to a safe positive window [low, high]
    if approx is None:
        approx = 1
    if approx < 1:
        approx = 1
    low = max(1, approx // 2)
    high = max(low, approx)
    mode = r.choice(['ascii', 'binary', 'mix'])
    if mode == 'ascii':
        return _clip(_rand_ascii(r, low, high).encode('ascii'))
    elif mode == 'binary':
        return _clip(_rand_bytes(r, low, high))
    else:
        a = _rand_ascii(r, low, high).encode('ascii')
        b = _rand_bytes(r, 0, max(0, approx // 3))
        return _clip(a + b)

def _build_command_tokens(r: random.Random) -> List[bytes]:
    def cmd_set():
        key = _rand_ascii(r, 1, 32)
        val = _make_bulk(r, r.randint(1, 300))
        opts = []
        if r.random() < 0.5:
            opts.extend([b'EX', _int_to_bytes(r.randint(1, 600))])
        if r.random() < 0.5:
            opts.extend([b'PX', _int_to_bytes(r.randint(1, 100000))])
        if r.random() < 0.5:
            opts.append(r.choice([b'NX', b'XX']))
        return [b'SET', key.encode('ascii'), val] + opts

    def cmd_get():
        key = _rand_ascii(r, 1, 32)
        return [b'GET', key.encode('ascii')]

    def cmd_incrbyfloat():
        key = _rand_ascii(r, 1, 32)
        inc = _float_to_bytes(r.uniform(-1000.0, 1000.0))
        return [b'INCRBYFLOAT', key.encode('ascii'), inc]

    def cmd_hset():
        key = _rand_ascii(r, 1, 32)
        fields = []
        pairs = r.randint(1, 3)
        for _ in range(pairs):
            f = _rand_ascii(r, 1, 16).encode('ascii')
            v = _make_bulk(r, r.randint(1, 200))
            fields.extend([f, v])
        return [b'HSET', key.encode('ascii')] + fields

    def cmd_lpush():
        key = _rand_ascii(r, 1, 32)
        count = r.randint(1, 5)
        vals = [_make_bulk(r, r.randint(1, 120)) for _ in range(count)]
        return [b'LPUSH', key.encode('ascii')] + vals

    def cmd_zadd():
        key = _rand_ascii(r, 1, 32)
        count = r.randint(1, 4)
        args = []
        for _ in range(count):
            score = _float_to_bytes(r.uniform(-10000, 10000))
            member = _make_bulk(r, r.randint(1, 120))
            args.extend([score, member])
        opts = []
        if r.random() < 0.3:
            opts.append(r.choice([b'NX', b'XX']))
        if r.random() < 0.3:
            opts.append(b'CH')
        if r.random() < 0.3:
            opts.append(b'INCR')
        return [b'ZADD', key.encode('ascii')] + opts + args

    def cmd_eval():
        script = _clip(b"return ARGV[1] or KEYS[1]")
        numkeys = r.randint(0, 3)
        keys = [_rand_ascii(r, 1, 16).encode('ascii') for _ in range(numkeys)]
        argv_cnt = r.randint(0, 3)
        argv = [_make_bulk(r, r.randint(1, 64)) for _ in range(argv_cnt)]
        return [b'EVAL', script, _int_to_bytes(numkeys)] + keys + argv

    def cmd_publish():
        ch = _rand_ascii(r, 1, 24).encode('ascii')
        msg = _make_bulk(r, r.randint(1, 200))
        return [b'PUBLISH', ch, msg]

    def cmd_geoadd():
        key = _rand_ascii(r, 1, 32).encode('ascii')
        n = r.randint(1, 3)
        args = []
        for _ in range(n):
            lon = _float_to_bytes(r.uniform(-180, 180))
            lat = _float_to_bytes(r.uniform(-85, 85))
            member = _make_bulk(r, r.randint(1, 80))
            args.extend([lon, lat, member])
        return [b'GEOADD', key] + args

    def cmd_xadd():
        key = _rand_ascii(r, 1, 32).encode('ascii')
        idpart = r.choice([b'*', _int_to_bytes(r.randint(0, 2**31-1)) + b"-" + _int_to_bytes(r.randint(0, 2**31-1))])
        pairs = r.randint(1, 3)
        fields = []
        for _ in range(pairs):
            f = _rand_ascii(r, 1, 12).encode('ascii')
            v = _make_bulk(r, r.randint(1, 120))
            fields.extend([f, v])
        return [b'XADD', key, idpart] + fields

    templates = [
        cmd_set, cmd_get, cmd_incrbyfloat, cmd_hset, cmd_lpush,
        cmd_zadd, cmd_eval, cmd_publish, cmd_geoadd, cmd_xadd
    ]
    tmpl = r.choice(templates)
    tokens = tmpl()
    btoks = [_clip(t if isinstance(t, (bytes, bytearray)) else str(t).encode('utf-8')) for t in tokens]
    return btoks

def _encode_for_harness(strings: List[bytes], tail_uint: int) -> bytes:
    body = b"\x00".join(strings)
    if len(body) > 4000:
        body = body[:4000]
    return body + struct.pack('<I', tail_uint & 0xFFFFFFFF)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    tokens = _build_command_tokens(r)

    # Ensure at least 3 tokens for the SDS stub (1..3) and up to 4 for argv stub (1..4)
    while len(tokens) < 3:
        tokens.append(_clip(_make_bulk(r, r.randint(1, 64))))
    tokens = tokens[:4]
    if r.random() < 0.3 and len(tokens) < 4:
        tokens.append(_clip(_make_bulk(r, r.randint(1, 64))))

    tail_uint = r.getrandbits(32)
    buf = _encode_for_harness(tokens, tail_uint)
    return buf[:4096]

import random
import struct
import ipaddress

# Data type: IP/hostname string
# We generate a NUL-terminated textual network address suitable for TCP APIs.
# The fuzz stubs request strings for:
# - Remote IP/host (must be non-empty)
# - Optional source/bind address (must be non-empty)
# - Unix socket path via FUZZ_PARAM_FILENAME (not our type here)
# Our generator returns a bytes buffer that the fuzzer will consume to seed FUZZ_PARAM_STR.
# We include diverse valid values:
# - IPv4 literals (normal, edge ranges, broadcast-like, leading zeros, mixed lengths)
# - IPv6 literals (short/long forms, with zero compression, embedded IPv4, scoped)
# - Hostnames (simple, multi-label, hyphens, punycode-like, long labels within limits)
# The buffer contains one or more NUL-terminated strings concatenated, so multiple
# FUZZ_PARAM_STR calls can consume distinct values from the same buffer.

MAX_TOTAL = 4096

IPv4_COMMON = [
    "127.0.0.1", "0.0.0.0", "255.255.255.255", "192.168.1.1", "10.0.0.1",
    "172.16.0.1", "8.8.8.8", "1.1.1.1", "169.254.1.1", "224.0.0.1",
]

IPv6_COMMON = [
    "::1", "::", "2001:db8::1", "fe80::1", "ff02::1",
    "2001:4860:4860::8888", "2620:fe::fe", "2001:db8:0:0:0:0:2:1",
    "2001:db8::2:1", "::ffff:192.0.2.128",
]

HOSTNAMES_COMMON = [
    "localhost", "example.com", "redis.local", "test", "a", "aa",
    "sub.domain.example", "xn--exmple-cua.com", "a-b-c.example", "srv01",
]


def rand_ipv4(rng: random.Random) -> str:
    # Mix of common and random; ensure valid dotted-quad
    if rng.random() < 0.5:
        return rng.choice(IPv4_COMMON)
    # Generate random octets with occasional edge values
    def roct():
        x = rng.randrange(0, 256)
        if rng.random() < 0.2:
            x = rng.choice([0, 1, 127, 224, 255])
        return x
    o = [roct() for _ in range(4)]
    s = ".".join(str(v) for v in o)
    # Sometimes add leading zeros in octets (still valid text for many resolvers)
    if rng.random() < 0.3:
        parts = []
        for v in o:
            width = rng.choice([1, 2, 3])
            parts.append(str(v).rjust(width, "0"))
        s = ".".join(parts)
    return s


def rand_ipv6(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(IPv6_COMMON)
    # Build a random IPv6 with optional compression
    hextets = [rng.randrange(0, 0x10000) for _ in range(8)]
    # With some probability, embed IPv4 at the end
    embed_ipv4 = rng.random() < 0.2
    if embed_ipv4:
        ipv4 = rand_ipv4(rng)
        try:
            ipaddress.IPv4Address(ipv4)
            hextets[-2] = int(ipv4.split(".")[0]) * 256 + int(ipv4.split(".")[1])
            hextets[-1] = int(ipv4.split(".")[2]) * 256 + int(ipv4.split(".")[3])
        except Exception:
            embed_ipv4 = False
    # Choose a run to compress to ::
    compress = rng.random() < 0.8
    if compress:
        # Find longest zero run
        best_start, best_len = -1, 0
        cur_start, cur_len = -1, 0
        for i, v in enumerate(hextets):
            if v == 0:
                if cur_start == -1:
                    cur_start, cur_len = i, 1
                else:
                    cur_len += 1
            else:
                if cur_len > best_len:
                    best_start, best_len = cur_start, cur_len
                cur_start, cur_len = -1, 0
        if cur_len > best_len:
            best_start, best_len = cur_start, cur_len
        if best_len >= 2:
            # Build with compression
            left = hextets[:best_start]
            right = hextets[best_start + best_len :]
            left_s = ":".join(f"{x:x}" for x in left)
            right_s = ":".join(f"{x:x}" for x in right)
            if left_s and right_s:
                s = left_s + "::" + right_s
            elif left_s:
                s = left_s + "::"
            elif right_s:
                s = "::" + right_s
            else:
                s = "::"
        else:
            s = ":".join(f"{x:x}" for x in hextets)
    else:
        s = ":".join(f"{x:x}" for x in hextets)
    # Optionally append a scope id for link-local addresses
    if s.startswith("fe80:") and rng.random() < 0.5:
        s += "%" + rng.choice(["eth0", "en0", "wlan0", str(rng.randint(1, 10))])
    return s


def rand_hostname(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rng.choice(HOSTNAMES_COMMON)
    # Generate a valid hostname: labels 1-63 chars, total <= 253
    num_labels = rng.randint(1, 4)
    labels = []
    for i in range(num_labels):
        # label must not start or end with hyphen
        length = rng.randint(1, min(20, 63))
        chars = []
        for j in range(length):
            if j == 0 or j == length - 1:
                chars.append(rng.choice("abcdefghijklmnopqrstuvwxyz0123456789"))
            else:
                chars.append(rng.choice("abcdefghijklmnopqrstuvwxyz0123456789-"))
        labels.append("".join(chars))
    name = ".".join(labels)
    # Optionally append a trailing dot to form FQDN
    if rng.random() < 0.2:
        name += "."
    return name


def generate_strings(rng: random.Random, count: int) -> list[str]:
    out = []
    for _ in range(count):
        choice = rng.random()
        if choice < 0.4:
            out.append(rand_ipv4(rng))
        elif choice < 0.8:
            out.append(rand_ipv6(rng))
        else:
            out.append(rand_hostname(rng))
    return out


def pack_cstrings(strings: list[str]) -> bytes:
    b = bytearray()
    for s in strings:
        enc = s.encode('utf-8', 'strict')
        if len(b) + len(enc) + 1 > MAX_TOTAL:
            break
        b += enc + b"\x00"
    # Ensure at least one non-empty string
    if not b:
        b = bytearray(b"127.0.0.1\x00")
    return bytes(b)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide how many strings to include so multiple FUZZ_PARAM_STR calls can consume sequentially
    count = rng.randint(2, 8)
    strings = generate_strings(rng, count)
    return pack_cstrings(strings)

import random
import ipaddress
from typing import List

# This generator produces a single bytes buffer intended to seed FUZZ_PARAM_STR
# calls for hiredis async connect binding stubs. The stubs read two non-empty
# strings: remote IP/host and source (bind) address. We pack two NUL-terminated
# strings back-to-back so fuzz harnesses that split by NULs (or read sequential
# C strings) get valid values.
#
# Goals:
# - Provide valid-looking remote targets: IPv4, IPv6 (with and without scope), and hostnames.
# - Provide valid local bind addresses: wildcard (0.0.0.0/::), loopback, link-local with scope ids,
#   and private ranges to exercise bind path variations.
# - Ensure non-empty strings to avoid FUZZ_BAIL in stubs.
# - Keep total size <= 4096 bytes.

MAX_TOTAL = 4096

_ipv4_priv = [
    ("10.0.0.1", "10.0.0.0/8"),
    ("172.16.0.10", "172.16.0.0/12"),
    ("192.168.1.50", "192.168.0.0/16"),
]

_ipv6_examples: List[str] = [
    "::1",
    "fe80::1%lo0",        # link-local with scope
    "fe80::1234%eth0",    # common Linux scope format
    "2001:db8::1",        # documentation global unicast
    "::ffff:192.0.2.128", # IPv4-mapped
]

_hostnames: List[str] = [
    "localhost",
    "redis",
    "example.com",
    "ipv6.google.com",
    "a.b.c.d",
]

_scopes: List[str] = ["lo0", "eth0", "en0", "wlan0", "eno1", "ens33"]


def _rand_hostname(r: random.Random) -> str:
    # Sometimes return from predefined list; sometimes construct a plausible FQDN
    if r.random() < 0.6:
        return r.choice(_hostnames)
    # Generate label parts 1-4 labels, each 1-10 chars a-z0-9
    labels = []
    for _ in range(r.randint(2, 4)):
        ln = r.randint(1, 10)
        s = ''.join(r.choice('abcdefghijklmnopqrstuvwxyz0123456789') for _ in range(ln))
        labels.append(s)
    return '.'.join(labels)


def _rand_ipv4(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.25:
        return "127.0.0.1"
    elif choice < 0.50:
        base = r.choice(_ipv4_priv)[0]
        # vary last octet
        parts = base.split('.')
        parts[-1] = str(r.randint(1, 254))
        return '.'.join(parts)
    elif choice < 0.75:
        # Random public-looking IPv4 excluding 0/127/255 in octets
        return '.'.join(str(r.randint(1, 254)) for _ in range(4))
    else:
        # Wildcard is not valid as remote; pick gateway-like
        return '192.0.2.' + str(r.randint(1, 254))  # TEST-NET-1


def _rand_ipv6(r: random.Random, allow_scope: bool) -> str:
    if r.random() < 0.5:
        s = r.choice(_ipv6_examples)
    else:
        # Random 128-bit, compress with ipaddress
        rnd = r.getrandbits(128)
        s = str(ipaddress.IPv6Address(rnd))
    if allow_scope and s.startswith('fe80::') and '%' not in s:
        s = s + '%' + r.choice(_scopes)
    return s


def _pick_remote(r: random.Random) -> str:
    t = r.random()
    if t < 0.4:
        return _rand_ipv4(r)
    elif t < 0.8:
        return _rand_ipv6(r, allow_scope=False)
    else:
        return _rand_hostname(r)


def _pick_bind(r: random.Random) -> str:
    # Bind addresses must be local interface addresses or wildcards
    t = r.random()
    if t < 0.25:
        return "0.0.0.0"
    elif t < 0.50:
        return "::"
    elif t < 0.65:
        return "127.0.0.1"
    elif t < 0.80:
        return "::1"
    elif t < 0.90:
        # IPv6 link-local with scope
        return "fe80::1%" + r.choice(_scopes)
    else:
        # Private v4 subnets
        return _rand_ipv4(r)


def _encode_c_strings(parts: List[str]) -> bytes:
    # Join NUL-terminated strings
    out = bytearray()
    for s in parts:
        # Ensure non-empty and no embedded NULs (C string safety)
        if not s:
            s = "x"
        s = s.replace('\x00', '')
        out += s.encode('utf-8', errors='ignore') + b"\x00"
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a scenario to exercise different paths in the target stubs
    scenario = r.randint(0, 7)

    if scenario == 0:
        # IPv4 remote + wildcard v4 bind
        remote = _rand_ipv4(r)
        bind = "0.0.0.0"
    elif scenario == 1:
        # IPv6 remote + wildcard v6 bind
        remote = _rand_ipv6(r, allow_scope=False)
        bind = "::"
    elif scenario == 2:
        # Hostname remote + loopback v4 bind
        remote = _rand_hostname(r)
        bind = "127.0.0.1"
    elif scenario == 3:
        # IPv4-mapped IPv6 remote + loopback v6 bind
        remote = "::ffff:" + _rand_ipv4(r)
        bind = "::1"
    elif scenario == 4:
        # IPv6 link-local remote (with optional scope) + link-local bind with scope
        remote = _rand_ipv6(r, allow_scope=True)
        if not remote.startswith('fe80::'):
            remote = 'fe80::1%' + r.choice(_scopes)
        bind = 'fe80::2%' + r.choice(_scopes)
    elif scenario == 5:
        # Documentation/test ranges
        remote = r.choice(["192.0.2.1", "198.51.100.2", "203.0.113.3", "2001:db8::5"])  # TEST-NETs
        bind = r.choice(["0.0.0.0", "::"]) 
    elif scenario == 6:
        # Long-ish hostname to test formatting paths
        label = ''.join(r.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(r.randint(10, 20)))
        remote = f"{label}.example.org"
        bind = _pick_bind(r)
    else:
        # Mixed random
        remote = _pick_remote(r)
        bind = _pick_bind(r)

    parts = [remote, bind]
    data = _encode_c_strings(parts)

    # Guard total size
    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]
    return data

