_MAX_OUT = 4096

def _rand_ascii_no_crlf(rng, min_len=0, max_len=64):
    n = rng.randint(min_len, max_len)
    # simple printable set without CR/LF
    chars = string.ascii_letters + string.digits + string.punctuation + ' '
    chars = chars.replace('\r', '').replace('\n', '')
    s = ''.join(rng.choice(chars) for _ in range(n))
    return s if s else "OK"

def _bulk(rng):
    data = rng.randbytes(rng.randint(0, 64)) if hasattr(rng, 'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(0,64))])
    return b"$" + str(len(data)).encode() + b"\r\n" + data + b"\r\n"

