    return b"+" + s.encode() + b"\r\n"

def _error(rng):
    s = _rand_ascii_no_crlf(rng, 1, 64)
    # Prepend a typical ERR prefix to be realistic
    if not s.startswith("ERR"):
        s = "ERR " + s
    return b"-" + s.encode() + b"\r\n"

def _integer(rng):
    # Small and large magnitudes, including negative and zero
    choices = [0, 1, -1, 42, -42, 2**31-1, -2**31, 2**63-1, -2**63+1]
    if rng.random() < 0.6:
        val = rng.choice(choices)
    else:
        val = rng.randint(-10**9, 10**9)
    return b":" + str(int(val)).encode() + b"\r\n"

def _double_bulk(rng):
    # RESP2 has no native double; hiredis exposes doubles in redisReply for RESP3.
    # To keep compatibility with RESP2/3 reader, encode as bulk string textual double.
    # Use interesting textual representations.
    specials = ["inf", "-inf", "nan", "0", "-0", "1.0", "-1.0", "1e309", "-1e309", "1e-309", "-1e-309"]
    if rng.random() < 0.5:
        s = rng.choice(specials)
    else:
        # Random formatted float
        val = (rng.random() - 0.5) * (10 ** rng.randint(-6, 6))
        s = ("%.*g" % (rng.randint(1, 16), val))
    b = s.encode()
    return b"$" + str(len(b)).encode() + b"\r\n" + b + b"\r\n"

def _array_of_ints(rng, count=None):
    if count is None:
        count = rng.randint(0, 8)
    parts = [b"*" + str(count).encode() + b"\r\n"]
    for _ in range(count):
        parts.append(_integer(rng))
    return b"".join(parts)

def _array_mixed_small(rng):
    # Build a small array mixing types (simple string, error, integer, bulk)
    items = []
    k = rng.randint(0, 6)
    for _ in range(k):
        t = rng.choice(["ss","err","int","bulk"]) 
        if t == "ss":
            items.append(_simple_string(rng))
        elif t == "err":
            items.append(_error(rng))
        elif t == "int":
            items.append(_integer(rng))
        else:
            items.append(_bulk(rng))
    return b"*" + str(len(items)).encode() + b"\r\n" + b"".join(items)

def _null_bulk():
    return b"$-1\r\n"

def _empty_array():
    return b"*0\r\n"

def _verbatim_string(rng):
    # RESP3 verbatim string: =<len>\r\n<vtype>:\n<data>\r\n where vtype is 3 bytes type, e.g., txt
    vtype = rng.choice([b"txt", b"mkd", b"htm", b"bin"])  # common examples
    data = (rng.choice([b"hello", b"world", b"verbatim", b"data"]) + (rng.randbytes(rng.randint(0,8)) if hasattr(rng,'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(0,8))])))
    payload = vtype + b":" + data
    return b"=" + str(len(payload)).encode() + b"\r\n" + payload + b"\r\n"

def _aggregate_frame(rng):
    # Build a small pipeline of multiple frames to exercise incremental parsing in feed
    parts = []
    for _ in range(rng.randint(2, 5)):
        parts.append(_choose_frame(rng))
    return b"".join(parts)

def _choose_frame(rng):
    # Weighted mix of valid RESP frames
    choices = [
        (3, _simple_string),
        (2, _error),
        (3, _integer),
        (4, _bulk),
        (2, _array_of_ints),
        (2, _array_mixed_small),
        (1, _null_bulk),
        (1, _empty_array),
        (1, _double_bulk),
        (1, _verbatim_string),
    ]
    total = sum(w for w,_ in choices)
    pick = rng.randrange(total)
    acc = 0
    for w, fn in choices:
        if pick < acc + w:
            if fn in (_null_bulk, _empty_array):
                return fn()
            elif fn in (_array_of_ints, _array_mixed_small):
                return fn(rng)
            else:
                return fn(rng)
        acc += w
    return _simple_string(rng)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.choice([
        "single_simple", "single_error", "single_integer", "single_bulk",
        "single_array_ints", "single_array_mixed", "null_bulk", "empty_array",
        "double_bulk", "verbatim", "pipeline"
    ])

    if mode == "single_simple":
        out = _simple_string(rng)
    elif mode == "single_error":
        out = _error(rng)
    elif mode == "single_integer":
        out = _integer(rng)
    elif mode == "single_bulk":
        out = _bulk(rng)
    elif mode == "single_array_ints":
        out = _array_of_ints(rng)
    elif mode == "single_array_mixed":
        out = _array_mixed_small(rng)
    elif mode == "null_bulk":
        out = _null_bulk()
    elif mode == "empty_array":
        out = _empty_array()
    elif mode == "double_bulk":
        out = _double_bulk(rng)
    elif mode == "verbatim":
        out = _verbatim_string(rng)
    else:  # pipeline
        out = _aggregate_frame(rng)

    # Ensure non-empty and within limits; if empty, fall back to simple string.
    if not out:
        out = b"+OK\r\n"
    if len(out) > _MAX_OUT:
        out = out[:_MAX_OUT]
    return out

import random
import struct
import string

# Generate valid RESP replies that hiredis redisReader can parse.
# We cover: Simple String, Error, Integer, Bulk String (including empty and binary-safe),
# Array (nested, heterogeneous), Nulls, Booleans (RESP3), Double (RESP3), Verbatim string (RESP3),
# Big number (RESP3), Map/Set (small to keep size low), Push (RESP3).

CRLF = b"\r\n"

_ascii = string.ascii_letters + string.digits + " _-:.#/+[]{}()@,;!$%^&*?=<>|~"


def _rand_ascii(rng: random.Random, n: int) -> bytes:
    return ''.join(rng.choice(_ascii) for _ in range(n)).encode('utf-8')


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Include a range of interesting bytes, including NUL and high bytes.
    return bytes(rng.randrange(0, 256) for _ in range(n))


def resp_simple_string(s: bytes) -> bytes:
    # Simple string MUST NOT contain CR or LF; sanitize by replacing
    s = s.replace(b"\r", b" ").replace(b"\n", b" ")
    return b"+" + s + CRLF


def resp_error(s: bytes) -> bytes:
    s = s.replace(b"\r", b" ").replace(b"\n", b" ")
    if not s:
        s = b"ERR"
    return b"-" + s + CRLF


def resp_integer(n: int) -> bytes:
    return b":" + str(n).encode() + CRLF


def resp_bulk(b: bytes) -> bytes:
    return b"$" + str(len(b)).encode() + CRLF + b + CRLF


def resp_null_bulk() -> bytes:
    return b"$-1" + CRLF


def resp_array(items: list[bytes]) -> bytes:
    return b"*" + str(len(items)).encode() + CRLF + b"".join(items)


def resp_null_array() -> bytes:
    return b"*-1" + CRLF

# RESP3 helpers

def resp_bool(val: bool) -> bytes:
    return (b"#t" if val else b"#f") + CRLF


def resp_double(d: float) -> bytes:
    # Use finite numbers and some edge strings
    s = ("%.*g" % (17, d)).encode()
    return b"," + s + CRLF


def resp_verbatim(vtype3: bytes, payload: bytes) -> bytes:
    # vtype3 must be 3 ASCII chars like b"txt", b"mkd", b"bin"
    vtype3 = (vtype3 or b"txt")[:3].ljust(3, b" ")
    body = vtype3 + b":" + payload
    return b"=" + str(len(body)).encode() + CRLF + body + CRLF


def resp_bignum(s: bytes) -> bytes:
    # Digits with optional sign; ensure at least one digit
    if not s or any(c not in b"0123456789" for c in s.strip(b"+ -")):
        s = b""  # force regenerate
    if not s:
        s = b"9" * 30
    return b"(" + s + CRLF


def resp_null() -> bytes:
    return b"_" + CRLF


def resp_blob_error(code: bytes, msg: bytes) -> bytes:
    # RESP3 blob error: !<len>\r\n<data>\r\n where data like "ERR message"
    data = code + b" " + msg.replace(b"\r", b" ").replace(b"\n", b" ")
    return b"!" + str(len(data)).encode() + CRLF + data + CRLF


def resp_map(pairs: list[tuple[bytes, bytes]]) -> bytes:
    # RESP3 map: %<n> CRLF key1 val1 key2 val2 ... (each is a RESP type)
    buf = b"%" + str(len(pairs)).encode() + CRLF
    for k, v in pairs:
        buf += k + v
    return buf


def resp_set(items: list[bytes]) -> bytes:
    buf = b"~" + str(len(items)).encode() + CRLF + b"".join(items)
    return buf


def resp_push(items: list[bytes]) -> bytes:
    buf = b">" + str(len(items)).encode() + CRLF + b"".join(items)
    return buf


def _small_nested_array(rng: random.Random) -> bytes:
    # Build a small nested array mixing types
    leaf_choices = []
    leaf_choices.append(resp_simple_string(b"OK"))
    leaf_choices.append(resp_error(b"ERR nested"))
    leaf_choices.append(resp_integer(rng.randint(-5, 5)))
    leaf_choices.append(resp_bulk(_rand_bytes(rng, rng.randint(0, 6))))
    leaf_choices.append(resp_bool(rng.choice([True, False])))
    leaf_choices.append(resp_double(rng.uniform(-1e3, 1e3)))
    inner = resp_array([rng.choice(leaf_choices) for _ in range(rng.randint(0, 3))])
    outer = resp_array([
        rng.choice(leaf_choices),
        inner,
        resp_null_bulk() if rng.random() < 0.3 else resp_bulk(_rand_bytes(rng, rng.randint(0, 4)))
    ])
    return outer


def _resp3_pairs(rng: random.Random, n: int) -> list[tuple[bytes, bytes]]:
    keys = []
    for _ in range(n):
        k = resp_bulk(_rand_ascii(rng, rng.randint(1, 6)))
        vtype = rng.randrange(0, 5)
        if vtype == 0:
            v = resp_integer(rng.randint(0, 100))
        elif vtype == 1:
            v = resp_simple_string(_rand_ascii(rng, rng.randint(2, 8)))
        elif vtype == 2:
            v = resp_bool(rng.choice([True, False]))
        elif vtype == 3:
            v = resp_double(rng.uniform(-1000, 1000))
        else:
            v = resp_bulk(_rand_bytes(rng, rng.randint(0, 10)))
        keys.append((k, v))
    return keys


def _choose_resp_frame(rng: random.Random) -> bytes:
    # Weighted choice among many valid frame kinds
    kinds = [
        "simple", "error", "integer", "bulk", "emptybulk", "nullbulk",
        "array2", "array_nested", "nullarray",
        "bool", "double", "verbatim", "bignum", "null",
        "bloberror", "map", "set", "push"
    ]
    kind = rng.choice(kinds)

    if kind == "simple":
        return resp_simple_string(_rand_ascii(rng, rng.randint(1, 32)))
    if kind == "error":
        return resp_error(b"ERR " + _rand_ascii(rng, rng.randint(1, 28)))
    if kind == "integer":
        n = rng.choice([0, 1, -1, 42, -42, 2**31-1, -2**31, rng.randint(-10**10, 10**10)])
        return resp_integer(n)
    if kind == "bulk":
        # binary-safe, include potential NULs
        size = rng.randint(0, 64)
        data = _rand_bytes(rng, size)
        return resp_bulk(data)
    if kind == "emptybulk":
        return resp_bulk(b"")
    if kind == "nullbulk":
        return resp_null_bulk()
    if kind == "array2":
        items = [resp_simple_string(b"OK"), resp_integer(1)]
        return resp_array(items)
    if kind == "array_nested":
        return _small_nested_array(rng)
    if kind == "nullarray":
        return resp_null_array()
    if kind == "bool":
        return resp_bool(rng.choice([True, False]))
    if kind == "double":
        val = rng.choice([0.0, -0.0, 1.0, -1.0, 1e10, -1e-10, rng.uniform(-1e6, 1e6)])
        return resp_double(val)
    if kind == "verbatim":
        vtype = rng.choice([b"txt", b"mkd", b"bin"])
        payload = _rand_bytes(rng, rng.randint(0, 32))
        return resp_verbatim(vtype, payload)
    if kind == "bignum":
        digits = b"".join(bytes([ord('0') + rng.randrange(10)]) for _ in range(rng.randint(1, 40)))
        sign = rng.choice([b"", b"+", b"-"])
        return resp_bignum(sign + digits)
    if kind == "null":
        return resp_null()
    if kind == "bloberror":
        code = rng.choice([b"ERR", b"BUSY", b"OOM", b"NOPERM"]) \
            + (b".AUTH" if rng.random() < 0.2 else b"")
        msg = _rand_ascii(rng, rng.randint(3, 40))
        return resp_blob_error(code, msg)
    if kind == "map":
        pairs = _resp3_pairs(rng, rng.randint(0, 4))
        return resp_map(pairs)
    if kind == "set":
        items = [resp_bulk(_rand_ascii(rng, rng.randint(1, 8))) for _ in range(rng.randint(0, 5))]
        return resp_set(items)
    if kind == "push":
        items = [
            resp_simple_string(b"message"),
            resp_bulk(_rand_ascii(rng, rng.randint(1, 6))),
            resp_bulk(_rand_bytes(rng, rng.randint(0, 16)))
        ]
        return resp_push(items)

    # Fallback
    return resp_simple_string(b"OK")


def _maybe_concat_frames(rng: random.Random, first: bytes) -> bytes:
    # Sometimes return a single reply; sometimes a frame followed by extra valid frames.
    # The fuzz stub expects a single reply parsed; redisReaderGetReply will parse one and leave the rest.
    buf = first
    # Cap total size to 4096
    while len(buf) < 1024 and rng.random() < 0.25:
        nxt = _choose_resp_frame(rng)
        if len(buf) + len(nxt) > 4096:
            break
        buf += nxt
    return buf


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a frame and maybe append additional ones (still valid RESP stream).
    frame = _choose_resp_frame(rng)
    frame = _maybe_concat_frames(rng, frame)
    # Ensure non-empty and under size limit
    if not frame:
        frame = resp_simple_string(b"OK")
    if len(frame) > 4096:
        frame = frame[:4096]
    return frame
